import { useEffect, useMemo, useState, type FormEvent, type ReactNode } from 'react';
import { createRoot } from 'react-dom/client';
import { createClient, type Session, type SupabaseClient } from '@supabase/supabase-js';
import './styles.css';

const SUPABASE_URL = import.meta.env.VITE_SUPABASE_URL;
const SUPABASE_KEY = import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY || import.meta.env.VITE_SUPABASE_ANON_KEY;
const supabase: SupabaseClient | null = SUPABASE_URL && SUPABASE_KEY ? createClient(SUPABASE_URL, SUPABASE_KEY) : null;
const images = { hero: '/stitch/hero-plush-group.png', bear: '/stitch/barnaby.png', blanket: '/stitch/blanket.png', gift: '/stitch/gift-box.png', lifestyle: '/stitch/gift-lifestyle.png', about: '/stitch/about-hero.png', contact: '/stitch/contact-hero.png' };

type Category = { id: string; name: string; slug: string };
type Product = { id: string; slug: string; name: string; short_description: string | null; description: string | null; price: number; compare_at_price: number | null; currency: string; sku: string; stock_quantity: number; is_featured: boolean; is_new: boolean; image: string | null; material: string | null; dimensions: string | null; care_instructions: string | null; age_guidance: string | null; category: Category | null; product_images: Array<{ image_url: string; alt_text: string | null; sort_order: number }> };
type Shipping = { id: string; country_code: string; currency: string; flat_amount: number; free_shipping_threshold: number | null; estimated_delivery: string };
type PaymentMethod = { method: 'cod' | 'bank_transfer' | 'card'; currency: string; fee_amount: number; instructions: string | null; bank_name: string | null; account_name: string | null; account_number: string | null; branch: string | null };
type Settings = { currency: string | null; locale: string | null; site_name: string; site_description: string | null; business_email: string | null; business_phone: string | null; whatsapp_url: string | null; instagram_url: string | null; facebook_url: string | null; tiktok_url: string | null; location: string | null; privacy_policy: string | null; terms_text: string | null; shipping_policy: string | null; returns_policy: string | null };
type CartLine = { productId: string; quantity: number };
type Quote = { currency: string; items: Array<{ product_id: string; quantity: number; unit_price: number; line_total: number; name: string; image: string | null }>; subtotal: number; shipping_amount: number; payment_fee: number; grand_total: number; shipping_estimate: string };
type Receipt = Record<string, unknown> & { confirmation_token?: string; items?: Array<Record<string, unknown>> };

const iconPaths: Record<string, string> = { search: 'M11 19a8 8 0 1 1 0-16 8 8 0 0 1 0 16Zm10 2-4.35-4.35', heart: 'M20.8 8.7c0 5.5-8.8 10.2-8.8 10.2S3.2 14.2 3.2 8.7A4.7 4.7 0 0 1 12 6a4.7 4.7 0 0 1 8.8 2.7Z', user: 'M20 21a8 8 0 0 0-16 0M12 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8Z', bag: 'M5 8h14l-1 13H6L5 8Zm3 0V6a4 4 0 0 1 8 0v2', menu: 'M4 7h16M4 12h16M4 17h16', close: 'M6 6l12 12M18 6 6 18', plus: 'M12 5v14M5 12h14', minus: 'M5 12h14', trash: 'M6 7h12m-9 0V5h6v2m-7 3v7m4-7v7m4-7v7M7 7l1 14h8l1-14', truck: 'M3 6h11v10H3zM14 10h4l3 3v3h-7zM7 19a2 2 0 1 0 0-4 2 2 0 0 0 0 4Zm11 0a2 2 0 1 0 0-4 2 2 0 0 0 0 4Z', lock: 'M6 10h12v10H6zM8 10V7a4 4 0 0 1 8 0v3', check: 'm5 12 4 4L19 6', gift: 'M4 10h16v10H4zM12 10v10M3 7h18v3H3zM12 7H8a2 2 0 1 1 4 0v0Zm0 0h4a2 2 0 1 0-4 0v0Z', pin: 'M20 10c0 5-8 11-8 11S4 15 4 10a8 8 0 1 1 16 0Z M12 12a2 2 0 1 0 0-4 2 2 0 0 0 0 4Z' };
function Icon({ name, size = 20 }: { name: string; size?: number }) { return <svg className="icon" width={size} height={size} viewBox="0 0 24 24" aria-hidden="true" fill="none"><path d={iconPaths[name] ?? iconPaths.check} stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" /></svg>; }
function navigate(path: string) { window.history.pushState({}, '', path); window.dispatchEvent(new PopStateEvent('popstate')); window.scrollTo(0, 0); }
function notify(message: string) { window.dispatchEvent(new CustomEvent('soft-haven-notice', { detail: message })); }
function readCart(): CartLine[] { try { const value = JSON.parse(localStorage.getItem('antz-soft-haven-cart') ?? '[]') as unknown; return Array.isArray(value) ? value.filter((line): line is CartLine => Boolean(line && typeof line === 'object' && typeof (line as CartLine).productId === 'string' && Number.isInteger((line as CartLine).quantity) && (line as CartLine).quantity > 0)) : []; } catch { return []; } }
function money(value: number, currency?: string | null, locale?: string | null) { if (!currency) return 'Price unavailable'; try { return new Intl.NumberFormat(locale || 'en', { style: 'currency', currency, currencyDisplay: 'code' }).format(value); } catch { return `${currency} ${value.toFixed(2)}`; } }
function Button({ children, onClick, type = 'button', outline = false, disabled = false }: { children: ReactNode; onClick?: () => void; type?: 'button' | 'submit'; outline?: boolean; disabled?: boolean }) { return <button type={type} onClick={onClick} disabled={disabled} className={`pill ${outline ? 'outline' : 'primary'}`}>{children}</button>; }
function ToastHost() { const [message, setMessage] = useState(''); useEffect(() => { const listener = (event: Event) => { setMessage((event as CustomEvent<string>).detail); window.setTimeout(() => setMessage(''), 3200); }; window.addEventListener('soft-haven-notice', listener); return () => window.removeEventListener('soft-haven-notice', listener); }, []); return message ? <div className="toast" role="status" aria-live="polite">{message}</div> : null; }

function useCatalog() { const [state, setState] = useState<{ products: Product[]; categories: Category[]; shipping: Shipping[]; payments: PaymentMethod[]; settings: Settings | null; loading: boolean; error: string | null }>({ products: [], categories: [], shipping: [], payments: [], settings: null, loading: true, error: null }); useEffect(() => { if (!supabase) { setState((current) => ({ ...current, loading: false, error: 'Store configuration is not connected.' })); return; } (async () => { const [productResult, categoryResult, shippingResult, paymentResult, settingsResult] = await Promise.all([supabase.from('products').select('id,slug,name,short_description,description,price,compare_at_price,currency,sku,stock_quantity,is_featured,is_new,image,material,dimensions,care_instructions,age_guidance,category:categories(id,name,slug),product_images(image_url,alt_text,sort_order)').eq('is_active', true).order('created_at', { ascending: false }), supabase.from('categories').select('id,name,slug').eq('is_active', true).order('name'), supabase.from('shipping_settings').select('id,country_code,currency,flat_amount,free_shipping_threshold,estimated_delivery').eq('is_active', true), supabase.from('payment_method_settings').select('method,currency,fee_amount,instructions,bank_name,account_name,account_number,branch').eq('enabled', true), supabase.from('site_settings').select('currency,locale,site_name,site_description,business_email,business_phone,whatsapp_url,instagram_url,facebook_url,tiktok_url,location,privacy_policy,terms_text,shipping_policy,returns_policy').eq('id', 1).eq('is_public', true).maybeSingle()]); const firstError = productResult.error || categoryResult.error || shippingResult.error || paymentResult.error || settingsResult.error; if (firstError) { setState((current) => ({ ...current, loading: false, error: 'Store data is not available yet. Please try again later.' })); return; } const productsData = (productResult.data ?? []).map((row) => { const item = row as unknown as Record<string, unknown>; const category = Array.isArray(item.category) ? (item.category[0] as Category | undefined) ?? null : (item.category as Category | null); return { ...item, price: Number(item.price), compare_at_price: item.compare_at_price == null ? null : Number(item.compare_at_price), stock_quantity: Number(item.stock_quantity), category, product_images: (item.product_images as Product['product_images'] | null) ?? [] } as Product; }); setState({ products: productsData, categories: (categoryResult.data ?? []) as Category[], shipping: (shippingResult.data ?? []).map((item) => ({ ...item, flat_amount: Number(item.flat_amount), free_shipping_threshold: item.free_shipping_threshold == null ? null : Number(item.free_shipping_threshold) })) as Shipping[], payments: (paymentResult.data ?? []).map((item) => ({ ...item, fee_amount: Number(item.fee_amount) })) as PaymentMethod[], settings: settingsResult.data as Settings | null, loading: false, error: null }); })(); }, []); return state; }

function Header({ cartCount, onSearch }: { cartCount: number; onSearch: () => void }) { const [open, setOpen] = useState(false); const links = [['Home', '/'], ['Shop', '/shop'], ['Collections', '/collections'], ['About', '/about'], ['Contact', '/contact']]; return <><div className="delivery"><span><Icon name="truck" size={14} /> A softer way to shop plush companions</span><span>ANTZ SoftHaven <i>♡</i></span></div><header className="site-header"><button className="mobile-toggle" aria-label={open ? 'Close menu' : 'Open menu'} aria-expanded={open} onClick={() => setOpen(!open)}><Icon name={open ? 'close' : 'menu'} /></button><a className="brand" href="/" onClick={(event) => { event.preventDefault(); setOpen(false); navigate('/'); }}><strong>ANTZ <span>SoftHaven</span></strong><small>Elegance in Every Cuddle</small></a><nav aria-label="Primary navigation" className={open ? 'nav open' : 'nav'}>{links.map(([label, path]) => <a key={path} href={path} className={window.location.pathname === path ? 'active' : ''} onClick={(event) => { event.preventDefault(); setOpen(false); navigate(path); }}>{label}</a>)}</nav><div className="header-actions"><button aria-label="Search" onClick={onSearch}><Icon name="search" /></button><button aria-label={`Cart, ${cartCount} items`} className="bag-btn" onClick={() => navigate('/cart')}><Icon name="bag" /><b>{cartCount}</b></button></div></header></>; }
function Footer({ settings }: { settings: Settings | null }) { const socials = [['Instagram', settings?.instagram_url], ['Facebook', settings?.facebook_url], ['TikTok', settings?.tiktok_url], ['WhatsApp', settings?.whatsapp_url]].filter((item): item is [string, string] => Boolean(item[1])); const policies = [['Shipping', '/shipping'], ['Returns', '/returns'], ['Privacy', '/privacy'], ['Terms', '/terms'], ['Contact', '/contact']]; return <footer><div className="footer-grid"><div><a className="footer-brand" href="/" onClick={(event) => { event.preventDefault(); navigate('/'); }}><strong>ANTZ SoftHaven</strong><small>Elegance in Every Cuddle</small></a><p>{settings?.site_description || 'Premium plush companions and meaningful gifts.'}</p><div className="socials" aria-label="Social media">{socials.map(([label, url]) => <a href={url} target="_blank" rel="noopener noreferrer" aria-label={label} key={label}>{label.slice(0, 1)}</a>)}</div></div><div><h3>Explore</h3><a href="/shop" onClick={(event) => { event.preventDefault(); navigate('/shop'); }}>Shop</a><a href="/collections" onClick={(event) => { event.preventDefault(); navigate('/collections'); }}>Collections</a><a href="/about" onClick={(event) => { event.preventDefault(); navigate('/about'); }}>About</a><a href="/contact" onClick={(event) => { event.preventDefault(); navigate('/contact'); }}>Contact</a></div><div><h3>Customer care</h3>{policies.map(([label, path]) => <a key={path} href={path} onClick={(event) => { event.preventDefault(); navigate(path); }}>{label}</a>)}</div><div><h3>Get in touch</h3>{settings?.business_email && <a href={`mailto:${settings.business_email}`}>{settings.business_email}</a>}{settings?.business_phone && <a href={`tel:${settings.business_phone}`}>{settings.business_phone}</a>}{settings?.location && <p>{settings.location}</p>}</div></div><div className="copyright">© {new Date().getFullYear()} ANTZ SoftHaven. All rights reserved.</div></footer>; }
function Layout({ children, settings, cartCount, onSearch }: { children: ReactNode; settings: Settings | null; cartCount: number; onSearch: () => void }) { return <div><Header cartCount={cartCount} onSearch={onSearch} />{children}<Footer settings={settings} /><ToastHost /></div>; }
function StoreState({ message }: { message: string }) { return <main className="page simple data-state"><span className="eyebrow">ANTZ SoftHaven</span><h1>{message}</h1><p>The live catalogue, currency, shipping and payment settings are configured securely in the store backend.</p><Button onClick={() => navigate('/contact')}>Contact the store</Button></main>; }

function ProductMedia({ product, large = false }: { product: Product; large?: boolean }) { const image = product.image || product.product_images[0]?.image_url; return image ? <img className={large ? 'product-media-large' : ''} src={image} alt={product.name} loading={large ? 'eager' : 'lazy'} /> : <div className="product-image-missing" role="img" aria-label={`${product.name} image not available`}>Image coming soon</div>; }
function ProductCard({ product, onAdd }: { product: Product; onAdd: (id: string) => void }) { const available = product.stock_quantity > 0; return <article className="shop-product-card"><a className="shop-product-image" href={`/product/${product.slug}`} onClick={(event) => { event.preventDefault(); navigate(`/product/${product.slug}`); }}><ProductMedia product={product} />{product.is_new && <span className="product-badge">New</span>}</a><div className="shop-product-copy"><h3><a href={`/product/${product.slug}`} onClick={(event) => { event.preventDefault(); navigate(`/product/${product.slug}`); }}>{product.name}</a></h3><p>{product.category?.name || 'Plush companion'}</p><div className="shop-product-row"><strong>{money(product.price, product.currency)}</strong><Button disabled={!available} onClick={() => onAdd(product.id)}>{available ? 'Add to cart' : 'Out of stock'}</Button></div></div></article>; }

function Home({ products, categories, onAdd, settings, configured }: { products: Product[]; categories: Category[]; onAdd: (id: string) => void; settings: Settings | null; configured: boolean }) { const featured = products.filter((product) => product.is_featured).slice(0, 4); return <main className="home-page"><section className="hero new-hero"><div className="hero-copy"><span className="eyebrow">MORE THAN JUST A TOY <i>♡</i></span><h1>Little Moments.<br /><em>Lasting Smiles.</em></h1><p>{settings?.site_description || 'Premium plush companions and meaningful gifts, designed to bring comfort and joy to everyday moments.'}</p><div className="button-row"><Button onClick={() => navigate('/shop')}>Shop Now <span>→</span></Button><Button outline onClick={() => navigate('/collections')}>Explore Collections <span>→</span></Button></div></div><div className="hero-art"><img className="hero-plush-group" src={images.hero} alt="A group of pastel plush companions" /></div></section><section className="benefits glass-panel"><div><span><Icon name="gift" /></span><b>Thoughtful gifting</b><small>Choose a companion for the moment.</small></div><div><span><Icon name="lock" /></span><b>Secure checkout</b><small>Your order is handled by the store backend.</small></div><div><span><Icon name="truck" /></span><b>Clear delivery</b><small>Shipping is shown before you place an order.</small></div></section>{configured && <section className="collections-section"><div className="section-intro"><span className="eyebrow">EXPLORE OUR WORLD <i>♡</i></span><h2>A Cuddle for <em>Every Heart.</em></h2><p>Browse the live collections currently available.</p></div><div className="collection-grid">{categories.slice(0, 6).map((category, index) => <a className={`collection-card ${['pink', 'lilac', 'blue', 'mint', 'peach', 'cream'][index % 6]}`} href={`/shop?category=${encodeURIComponent(category.slug)}`} key={category.id} onClick={(event) => { event.preventDefault(); navigate(`/shop?category=${encodeURIComponent(category.slug)}`); }}><img src={index % 2 ? images.bear : images.gift} alt="" loading="lazy" /><span>{category.name}<b>→</b></span></a>)}</div></section>}{featured.length > 0 && <section className="loved-section"><div className="section-row"><div><span className="eyebrow">CURATED FOR YOU <i>♡</i></span><h2>Meet the <em>soft friends.</em></h2></div><a className="text-link" href="/shop" onClick={(event) => { event.preventDefault(); navigate('/shop'); }}>View all →</a></div><div className="shop-product-grid">{featured.map((product) => <ProductCard product={product} onAdd={onAdd} key={product.id} />)}</div></section>}<section className="gift-banner"><div className="gift-photo"><img src={images.lifestyle} alt="A person hugging a teddy bear" loading="lazy" /></div><div className="gift-copy"><span className="eyebrow">MADE FOR MEANINGFUL MOMENTS <i>♡</i></span><h2>More Than a Gift.<br /><em>It’s a Feeling.</em></h2><p>Take your time and find the companion that feels just right.</p><Button onClick={() => navigate('/shop')}>Find a companion <span>→</span></Button></div></section></main>; }

function Collections({ categories, products, onAdd }: { categories: Category[]; products: Product[]; onAdd: (id: string) => void }) { return <main className="collections-page"><div className="breadcrumbs"><a href="/" onClick={(event) => { event.preventDefault(); navigate('/'); }}>Home</a><span>›</span><b>Collections</b></div><section className="collections-hero"><div><span className="eyebrow">FIND YOUR FAVOURITE <i>♡</i></span><h1>Collections made<br /><em>to cuddle.</em></h1><p>Browse the categories from the live catalogue.</p><Button onClick={() => navigate('/shop')}>Shop all plushies <span>→</span></Button></div><div className="collections-hero-art"><img src={images.hero} alt="Pastel plush companions" /></div></section><section className="collection-discovery"><div className="collection-bento">{categories.map((category, index) => <a className={`collection-tile ${['rose', 'lilac', 'blue', 'mint', 'peach', 'cream'][index % 6]}`} href={`/shop?category=${encodeURIComponent(category.slug)}`} key={category.id} onClick={(event) => { event.preventDefault(); navigate(`/shop?category=${encodeURIComponent(category.slug)}`); }}><img src={index % 2 ? images.bear : images.gift} alt="" loading="lazy" /><div className="collection-tile-caption"><span>{category.name}</span><small>{products.filter((product) => product.category?.id === category.id).length} available products</small><b>Browse <i>→</i></b></div></a>)}</div></section></main>; }

function Shop({ products, categories, onAdd }: { products: Product[]; categories: Category[]; onAdd: (id: string) => void }) { const params = new URLSearchParams(window.location.search); const [query, setQuery] = useState(params.get('q') || ''); const [category, setCategory] = useState(params.get('category') || ''); const [sort, setSort] = useState(params.get('sort') === 'new' ? 'new' : 'featured'); const filtered = useMemo(() => { const normalized = query.trim().toLowerCase(); return [...products].filter((product) => (!category || product.category?.slug === category) && (!normalized || `${product.name} ${product.short_description || ''} ${product.description || ''} ${product.category?.name || ''}`.toLowerCase().includes(normalized))).sort((a, b) => sort === 'price-low' ? a.price - b.price : sort === 'price-high' ? b.price - a.price : sort === 'new' ? Number(b.is_new) - Number(a.is_new) : Number(b.is_featured) - Number(a.is_featured)); }, [products, query, category, sort]); return <main className="page shop-page"><div className="breadcrumbs"><a href="/" onClick={(event) => { event.preventDefault(); navigate('/'); }}>Home</a><span>›</span><b>Shop</b></div><div className="shop-heading"><h1>Our <em>Shop</em></h1><p>Discover the products currently available from ANTZ SoftHaven.</p></div><div className="shop-layout"><aside className="filter-panel glass-panel" aria-label="Shop filters"><div className="filter-section"><h2>Categories</h2><button className={!category ? 'filter-option active' : 'filter-option'} onClick={() => setCategory('')}>All products <b>{products.length}</b></button>{categories.map((item) => <button className={category === item.slug ? 'filter-option active' : 'filter-option'} key={item.id} onClick={() => setCategory(item.slug)}>{item.name}<b>{products.filter((product) => product.category?.id === item.id).length}</b></button>)}</div></aside><section className="shop-results" aria-label="Products"><div className="shop-results-top"><span>{filtered.length} product{filtered.length === 1 ? '' : 's'}</span><label>Sort by <select aria-label="Sort products" value={sort} onChange={(event) => setSort(event.target.value)}><option value="featured">Featured</option><option value="new">New arrivals</option><option value="price-low">Price low</option><option value="price-high">Price high</option></select></label></div>{filtered.length ? <div className="shop-product-grid">{filtered.map((product) => <ProductCard product={product} onAdd={onAdd} key={product.id} />)}</div> : <div className="empty shop-empty"><h2>No soft finds yet.</h2><p>Try another search or category.</p><Button outline onClick={() => { setQuery(''); setCategory(''); }}>Clear filters</Button></div>}</section></div></main>; }

function ProductPage({ product, onAdd }: { product: Product | undefined; onAdd: (id: string) => void }) { const [quantity, setQuantity] = useState(1); if (!product) return <NotFound />; const available = product.stock_quantity > 0; return <main className="page product-page"><div className="breadcrumbs"><a href="/shop" onClick={(event) => { event.preventDefault(); navigate('/shop'); }}>Shop</a><span>›</span><b>{product.name}</b></div><div className="product-detail"><div className="main-product-image"><ProductMedia product={product} large /></div><section className="detail-card"><h1>{product.name}</h1><p className="collection">{product.category?.name || 'Plush companion'}</p><div className="price-line"><strong>{money(product.price, product.currency)}</strong></div><p className="description">{product.description || product.short_description || 'Product details will be added to the live catalogue.'}</p><p className={`stock-line ${available ? '' : 'out-of-stock'}`}>{available ? `${product.stock_quantity} available` : 'Out of stock'}</p>{product.sku && <p className="sku-line">SKU: {product.sku}</p>}{product.material && <p><b>Material:</b> {product.material}</p>}{product.dimensions && <p><b>Dimensions:</b> {product.dimensions}</p>}{product.care_instructions && <p><b>Care:</b> {product.care_instructions}</p>}{product.age_guidance && <p><b>Age guidance:</b> {product.age_guidance}</p>}<div className="quantity product-quantity"><button aria-label="Decrease quantity" disabled={quantity <= 1} onClick={() => setQuantity((value) => Math.max(1, value - 1))}><Icon name="minus" size={14} /></button><b>{quantity}</b><button aria-label="Increase quantity" disabled={quantity >= product.stock_quantity} onClick={() => setQuantity((value) => Math.min(product.stock_quantity, value + 1))}><Icon name="plus" size={14} /></button></div><Button disabled={!available} onClick={() => { for (let index = 0; index < quantity; index += 1) onAdd(product.id); notify(`${product.name} added to your cart.`); }}>Add to Cart · {money(product.price * quantity, product.currency)}</Button><p className="product-trust"><Icon name="truck" size={16} /> Shipping and return details are shown at checkout and in the store policies.</p></section></div></main>; }

function CartPage({ cart, products, setCart, settings }: { cart: CartLine[]; products: Product[]; setCart: (lines: CartLine[]) => void; settings: Settings | null }) { const lines = cart.map((line) => ({ ...line, product: products.find((product) => product.id === line.productId) })).filter((line): line is CartLine & { product: Product } => Boolean(line.product)); const subtotal = lines.reduce((sum, line) => sum + line.product.price * line.quantity, 0); const update = (id: string, quantity: number) => setCart(cart.map((line) => line.productId === id ? { ...line, quantity } : line).filter((line) => line.quantity > 0)); return <main className="page cart-page"><div className="breadcrumbs"><a href="/" onClick={(event) => { event.preventDefault(); navigate('/'); }}>Home</a><span>›</span><b>Your cart</b></div><h1>Your <em>cart.</em></h1>{cart.length === 0 ? <div className="empty cart-empty"><Icon name="bag" size={42} /><h2>Your cart is waiting.</h2><p>Choose a soft companion to get started.</p><Button onClick={() => navigate('/shop')}>Explore the shop</Button></div> : <div className="cart-layout"><section className="cart-lines">{cart.map((line) => { const product = products.find((item) => item.id === line.productId); if (!product) return <article className="cart-line stale" key={line.productId}><p>This product is no longer available.</p><Button outline onClick={() => setCart(cart.filter((item) => item.productId !== line.productId))}>Remove</Button></article>; return <article className="cart-line" key={line.productId}><ProductMedia product={product} /><div><h3>{product.name}</h3><p>{money(product.price, product.currency)}</p><div className="quantity"><button aria-label="Decrease quantity" disabled={line.quantity <= 1} onClick={() => update(line.productId, line.quantity - 1)}><Icon name="minus" size={14} /></button><b>{line.quantity}</b><button aria-label="Increase quantity" disabled={line.quantity >= product.stock_quantity} onClick={() => update(line.productId, line.quantity + 1)}><Icon name="plus" size={14} /></button></div></div><strong>{money(product.price * line.quantity, product.currency)}</strong><button className="delete" aria-label={`Remove ${product.name}`} onClick={() => setCart(cart.filter((item) => item.productId !== product.id))}><Icon name="trash" size={18} /></button></article>; })}</section><aside className="cart-summary glass-panel"><h2>Summary</h2><div><span>Subtotal</span><strong>{money(subtotal, settings?.currency)}</strong></div><p>Shipping and any payment fee are calculated securely at checkout.</p><Button disabled={!lines.length} onClick={() => navigate('/checkout')}>Continue to checkout</Button><Button outline onClick={() => navigate('/shop')}>Continue shopping</Button></aside></div>}</main>; }

function Checkout({ cart, products, shipping, payments, settings, onSuccess }: { cart: CartLine[]; products: Product[]; shipping: Shipping[]; payments: PaymentMethod[]; settings: Settings | null; onSuccess: (receipt: Receipt) => void }) { const [form, setForm] = useState({ name: '', email: '', phone: '', address_line_1: '', address_line_2: '', city: '', postal_code: '', country: shipping[0]?.country_code || '' }); const [countryCode, setCountryCode] = useState(shipping[0]?.country_code || ''); const [paymentMethod, setPaymentMethod] = useState<PaymentMethod['method'] | ''>(payments.find((item) => item.method !== 'card')?.method || ''); const [notes, setNotes] = useState(''); const [quote, setQuote] = useState<Quote | null>(null); const [error, setError] = useState(''); const [working, setWorking] = useState(false); const lines = cart.filter((line) => products.some((product) => product.id === line.productId)); useEffect(() => { if (!supabase || !countryCode || !paymentMethod || !lines.length) return; supabase.functions.invoke('checkout-quote', { body: { items: lines.map((line) => ({ product_id: line.productId, quantity: line.quantity })), country_code: countryCode, payment_method: paymentMethod } }).then(({ data, error: invokeError }) => { if (invokeError) setQuote(null); else setQuote(data as Quote); }); }, [countryCode, paymentMethod, cart.length, products.length]); const update = (key: keyof typeof form) => (event: React.ChangeEvent<HTMLInputElement>) => setForm({ ...form, [key]: event.target.value }); if (!cart.length) return <StoreState message="Your cart is empty." />; if (!supabase) return <StoreState message="Checkout is not configured yet." />; const submit = async (event: FormEvent) => { event.preventDefault(); setError(''); if (!quote) { setError('Choose an available country and payment method to continue.'); return; } setWorking(true); const idempotencyKey = crypto.randomUUID(); const { data, error: invokeError } = await supabase.functions.invoke('checkout-create', { body: { customer: form, items: lines.map((line) => ({ product_id: line.productId, quantity: line.quantity })), country_code: countryCode, payment_method: paymentMethod, notes, idempotency_key: idempotencyKey } }); setWorking(false); if (invokeError || !data) { setError('We could not create the order. Your cart was not charged; please review and try again.'); return; } onSuccess(data as Receipt); }; return <main className="checkout page"><div className="checkout-logo">ANTZ SoftHaven <span><Icon name="lock" size={16} /> Secure checkout</span></div><div className="checkout-grid"><form onSubmit={submit}><section className="form-card"><h2>Contact and delivery</h2><div className="two"><Field label="Full name" value={form.name} onChange={update('name')} /><Field label="Email" value={form.email} onChange={update('email')} type="email" /></div><div className="two"><Field label="Phone" value={form.phone} onChange={update('phone')} /><Field label="City" value={form.city} onChange={update('city')} /></div><Field label="Address line 1" value={form.address_line_1} onChange={update('address_line_1')} /><Field label="Address line 2 (optional)" value={form.address_line_2} onChange={update('address_line_2')} required={false} /><div className="two"><Field label="Postal code (optional)" value={form.postal_code} onChange={update('postal_code')} required={false} /><label className="field"><span>Country</span><select required value={countryCode} onChange={(event) => { setCountryCode(event.target.value); setForm({ ...form, country: event.target.options[event.target.selectedIndex]?.text || event.target.value }); }}><option value="" disabled>Select a delivery country</option>{shipping.filter((item) => !settings?.currency || item.currency === settings.currency).map((item) => <option value={item.country_code} key={item.id}>{item.country_code}</option>)}</select></label></div><label className="field"><span>Order notes (optional)</span><textarea value={notes} onChange={(event) => setNotes(event.target.value)} maxLength={1000} /></label></section><section className="form-card"><h2>Payment method</h2>{payments.filter((item) => item.method !== 'card' && (!settings?.currency || item.currency === settings.currency)).map((method) => <label className={`payment-choice ${paymentMethod === method.method ? 'selected' : ''}`} key={method.method}><input type="radio" name="payment_method" value={method.method} checked={paymentMethod === method.method} onChange={() => setPaymentMethod(method.method)} /><span><b>{method.method === 'cod' ? 'Cash on delivery' : 'Bank transfer'}</b><small>{method.instructions || (method.method === 'cod' ? 'Pay when your order is delivered.' : 'Transfer after your order is created.')}</small></span><strong>{method.fee_amount ? money(method.fee_amount, method.currency) : 'No fee'}</strong></label>)}{!payments.filter((item) => item.method !== 'card').length && <p className="form-error">No payment method is enabled yet.</p>}</section>{error && <p className="form-error" role="alert">{error}</p>}<Button type="submit" disabled={working || !quote}>{working ? 'Creating order…' : 'Place order'}</Button></form><aside className="order-summary glass-panel"><h2>Order summary</h2>{quote ? <><div><span>Subtotal</span><strong>{money(quote.subtotal, quote.currency)}</strong></div><div><span>Shipping</span><strong>{money(quote.shipping_amount, quote.currency)}</strong></div><div><span>Payment fee</span><strong>{money(quote.payment_fee, quote.currency)}</strong></div><div className="grand-total"><span>Total</span><strong>{money(quote.grand_total, quote.currency)}</strong></div><p><Icon name="truck" size={15} /> {quote.shipping_estimate}</p></> : <p>Choose a delivery country and payment method for a server-calculated total.</p>}</aside></div></main>; }
function Field({ label, value, onChange, type = 'text', required = true }: { label: string; value: string; onChange: (event: React.ChangeEvent<HTMLInputElement>) => void; type?: string; required?: boolean }) { return <label className="field"><span>{label}</span><input type={type} value={value} onChange={onChange} required={required} /></label>; }

function OrderConfirmation({ settings, payments }: { settings: Settings | null; payments: PaymentMethod[] }) { const [receipt, setReceipt] = useState<Receipt | null>(null); const [loading, setLoading] = useState(true); useEffect(() => { try { const stored = sessionStorage.getItem('antz-soft-haven-order'); if (!stored) { setLoading(false); return; } const parsed = JSON.parse(stored) as Receipt; if (supabase && parsed.confirmation_token && parsed.order_number) supabase.functions.invoke('confirm-order', { body: { order_number: parsed.order_number, confirmation_token: parsed.confirmation_token } }).then(({ data }) => { setReceipt(data ? { ...parsed, ...data } : parsed); setLoading(false); }); else { setReceipt(parsed); setLoading(false); } } catch { setLoading(false); } }, []); if (loading) return <StoreState message="Loading your order…" />; if (!receipt) return <StoreState message="This order confirmation is no longer available." />; const items = Array.isArray(receipt.items) ? receipt.items : []; const bank = payments.find((item) => item.method === 'bank_transfer'); return <main className="page order-complete"><span className="eyebrow"><Icon name="check" /> Order received</span><h1>Thank you.</h1><p>Your order <strong>{String(receipt.order_number)}</strong> has been created.</p><div className="order-details glass-panel"><div><span>Total</span><strong>{money(Number(receipt.grand_total), String(receipt.currency || settings?.currency || ''))}</strong></div><div><span>Payment</span><strong>{String(receipt.payment_method)}</strong></div><div><span>Delivery</span><strong>{String(receipt.address_line_1)}, {String(receipt.city)}, {String(receipt.country)}</strong></div>{items.map((item, index) => <div key={index}><span>{String(item.product_name_snapshot)} × {String(item.quantity)}</span><strong>{money(Number(item.line_total), String(receipt.currency || settings?.currency || ''))}</strong></div>)}</div>{receipt.payment_method === 'bank_transfer' && bank && <div className="preview-notice" role="note"><b>Bank transfer instructions</b><p>{bank.instructions}</p><p>{bank.bank_name} · {bank.account_name} · {bank.account_number}{bank.branch ? ` · ${bank.branch}` : ''}</p></div>}<p>We’ll use the contact details in your order to send the next update when notification delivery is configured.</p><Button onClick={() => navigate('/shop')}>Continue shopping</Button></main>; }

function Contact({ settings }: { settings: Settings | null }) { const [form, setForm] = useState({ name: '', email: '', subject: '', message: '', website: '' }); const [state, setState] = useState<'idle' | 'working' | 'sent' | 'error'>('idle'); const submit = async (event: FormEvent) => { event.preventDefault(); if (!supabase) { setState('error'); return; } setState('working'); const { error } = await supabase.functions.invoke('contact-submit', { body: form }); setState(error ? 'error' : 'sent'); }; return <main className="contact-page"><section className="contact-main"><div className="contact-intro"><span className="eyebrow">GET IN TOUCH</span><h1>We’d love to<br /><em>hear</em> from you.</h1><p>Questions about a product or an order? Send a message to the store.</p><div className="contact-details glass-panel">{settings?.business_email && <a className="contact-row" href={`mailto:${settings.business_email}`}><span><Icon name="gift" /></span><div><b>Email</b><small>{settings.business_email}</small></div></a>}{settings?.business_phone && <a className="contact-row" href={`tel:${settings.business_phone}`}><span><Icon name="user" /></span><div><b>Phone</b><small>{settings.business_phone}</small></div></a>}{settings?.whatsapp_url && <a className="contact-row" href={settings.whatsapp_url} target="_blank" rel="noopener noreferrer"><span><Icon name="heart" /></span><div><b>WhatsApp</b><small>Message us</small></div></a>}{settings?.location && <div className="contact-row"><span><Icon name="pin" /></span><div><b>Location</b><small>{settings.location}</small></div></div>}</div></div><form className="contact-form glass-panel" onSubmit={submit}><h2>Send a message</h2><Field label="Your name" value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} /><Field label="Your email" value={form.email} onChange={(event) => setForm({ ...form, email: event.target.value })} type="email" /><Field label="Subject (optional)" value={form.subject} onChange={(event) => setForm({ ...form, subject: event.target.value })} required={false} /><label className="field"><span>Your message</span><textarea required minLength={10} maxLength={5000} value={form.message} onChange={(event) => setForm({ ...form, message: event.target.value })} /></label><label className="honeypot" aria-hidden="true">Website<input tabIndex={-1} autoComplete="off" value={form.website} onChange={(event) => setForm({ ...form, website: event.target.value })} /></label><Button type="submit" disabled={state === 'working' || state === 'sent'}>{state === 'working' ? 'Sending…' : state === 'sent' ? 'Message received' : 'Send message'}</Button>{state === 'error' && <p className="form-error" role="alert">The message could not be sent. Please try again.</p>}</form></section></main>; }
function About() { return <main className="about-page"><section className="about-hero"><div className="about-hero-copy"><span className="eyebrow">OUR STORY</span><h1>Soft friends for<br /><em>meaningful moments.</em></h1><p>ANTZ SoftHaven is a plush-toy store built around comfort, thoughtful gifting, and the small moments that make a day feel warmer.</p><Button onClick={() => navigate('/shop')}>Explore the shop</Button></div><div className="about-hero-art"><img src={images.about} alt="A teddy bear in a glass heart" /></div></section><section className="about-care"><div className="about-care-image"><img src={images.lifestyle} alt="A person hugging a teddy bear" loading="lazy" /></div><div className="about-care-copy"><span className="eyebrow">A SOFTER START</span><h2>Choose slowly.<br /><em>Gift thoughtfully.</em></h2><p>Live product pages show the materials, care information, availability, and shipping details supplied by the store.</p><Button outline onClick={() => navigate('/contact')}>Talk to us</Button></div></section></main>; }
const policyTitles: Record<string, string> = { '/privacy': 'Privacy policy', '/terms': 'Terms and conditions', '/shipping': 'Shipping policy', '/returns': 'Returns and refunds' };
function Legal({ path, settings }: { path: string; settings: Settings | null }) { const content = path === '/privacy' ? settings?.privacy_policy : path === '/terms' ? settings?.terms_text : path === '/shipping' ? settings?.shipping_policy : settings?.returns_policy; return <main className="page legal"><span className="eyebrow">ANTZ SoftHaven</span><h1>{policyTitles[path]}</h1>{content ? <div className="legal-copy">{content.split('\n').map((line, index) => <p key={index}>{line}</p>)}</div> : <div className="preview-notice"><b>This policy is not published yet.</b><p>The store owner must add final, jurisdiction-specific policy text before launch.</p></div>}</main>; }
function Faq() { return <main className="page legal"><span className="eyebrow">ANTZ SoftHaven</span><h1>Frequently asked questions</h1><div className="legal-copy"><p><b>How do I place an order?</b> Add an available product to your cart, enter your delivery details, and choose an enabled payment method.</p><p><b>When is payment taken?</b> Bank-transfer orders remain awaiting verification. Card payments are not enabled until the store owner configures a provider.</p><p><b>Where do you deliver?</b> Available delivery countries, charges, and estimates are shown at checkout from the store’s live shipping settings.</p><p><b>Need help with an order?</b> Use the contact page and include your order number where available.</p></div></main>; }
function NotFound() { return <main className="page simple"><span className="eyebrow">404 · Soft landing</span><h1>That page wandered off.</h1><p>We couldn’t find the page you requested.</p><Button onClick={() => navigate('/')}>Return home</Button></main>; }

function AdminApp({ route }: { route: string }) { const [session, setSession] = useState<Session | null>(null); const [authorized, setAuthorized] = useState(false); const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); const [error, setError] = useState(''); const [products, setProducts] = useState<Array<Record<string, unknown>>>([]); const [orders, setOrders] = useState<Array<Record<string, unknown>>>([]); const [section, setSection] = useState(route === '/admin/products' ? 'Products' : route === '/admin/orders' ? 'Orders' : 'Dashboard'); const [loading, setLoading] = useState(false); const [draft, setDraft] = useState({ id: '', name: '', slug: '', sku: '', price: '', currency: '', stock_quantity: '', image: '', description: '', category_id: '', is_active: false }); useEffect(() => { if (!supabase) return; supabase.auth.getSession().then(({ data }) => setSession(data.session)); const listener = supabase.auth.onAuthStateChange((_event, nextSession) => setSession(nextSession)); return () => listener.data.subscription.unsubscribe(); }, []); useEffect(() => { if (!session || !supabase) return; (async () => { const { data: admin } = await supabase.from('admin_users').select('user_id').eq('user_id', session.user.id).eq('is_active', true).maybeSingle(); if (!admin) { await supabase.auth.signOut(); setError('This account is not authorized for store administration.'); return; } setAuthorized(true); setLoading(true); const [productResult, orderResult] = await Promise.all([supabase.from('products').select('id,name,slug,sku,price,currency,stock_quantity,image,description,is_active,updated_at').order('updated_at', { ascending: false }), supabase.from('orders').select('id,order_number,customer_name,phone,grand_total,currency,payment_method,payment_status,order_status,created_at').order('created_at', { ascending: false }).limit(100)]); if (productResult.error || orderResult.error) setError('Admin data could not be loaded.'); else { setProducts((productResult.data ?? []) as Array<Record<string, unknown>>); setOrders((orderResult.data ?? []) as Array<Record<string, unknown>>); } setLoading(false); })(); }, [session]); const login = async (event: FormEvent) => { event.preventDefault(); if (!supabase) { setError('Supabase is not configured.'); return; } const { error: loginError } = await supabase.auth.signInWithPassword({ email, password }); if (loginError) setError('Sign-in failed. Check the authorized admin credentials.'); }; if (!session || !authorized) return <main className="admin-login"><form onSubmit={login}><span className="eyebrow">ANTZ SoftHaven · Admin</span><h1>Welcome back.</h1><p>Use an authorized Supabase account.</p><input type="email" placeholder="Email" value={email} onChange={(event) => setEmail(event.target.value)} required /><input type="password" placeholder="Password" value={password} onChange={(event) => setPassword(event.target.value)} required /><button className="admin-button" type="submit">Sign in</button>{error && <p className="admin-error">{error}</p>}</form></main>; const saveProduct = async (event: FormEvent) => { event.preventDefault(); if (!supabase) return; const payload = { name: draft.name.trim(), slug: draft.slug.trim(), sku: draft.sku.trim(), price: Number(draft.price), currency: draft.currency.trim().toUpperCase(), stock_quantity: Number(draft.stock_quantity), image: draft.image.trim() || null, description: draft.description.trim() || null, category_id: draft.category_id || null, is_active: draft.is_active }; const result = draft.id ? await supabase.from('products').update(payload).eq('id', draft.id) : await supabase.from('products').insert(payload); if (result.error) setError('Product could not be saved. Check all fields and unique slug/SKU.'); else { setDraft({ id: '', name: '', slug: '', sku: '', price: '', currency: '', stock_quantity: '', image: '', description: '', category_id: '', is_active: false }); const { data } = await supabase.from('products').select('id,name,slug,sku,price,currency,stock_quantity,image,description,is_active,updated_at').order('updated_at', { ascending: false }); setProducts((data ?? []) as Array<Record<string, unknown>>); } }; const updateOrder = async (id: string, orderStatus: string) => { if (!supabase) return; const result = await supabase.from('orders').update({ order_status: orderStatus }).eq('id', id); if (result.error) setError('Order status could not be updated.'); else setOrders(orders.map((order) => order.id === id ? { ...order, order_status: orderStatus } : order)); }; const revenue = orders.filter((order) => order.payment_status === 'paid').reduce((sum, order) => sum + Number(order.grand_total || 0), 0); return <div className="admin-shell"><aside className="admin-sidebar"><div className="admin-logo">ANTZ <span>SoftHaven</span></div><nav>{['Dashboard', 'Products', 'Orders'].map((item) => <button key={item} className={section === item ? 'active' : ''} onClick={() => setSection(item)}>{item}</button>)}</nav><button className="admin-logout" onClick={() => supabase?.auth.signOut()}>Log out</button></aside><main className="admin-main"><header className="admin-topbar"><div><span className="eyebrow">Operations</span><h1>{section}</h1></div><span className="admin-user">{session.user.email}</span></header>{loading && <div className="admin-state">Loading live data…</div>}{!loading && section === 'Dashboard' && <><div className="admin-stats"><article><small>Products</small><strong>{products.length}</strong></article><article><small>Orders</small><strong>{orders.length}</strong></article><article><small>New orders</small><strong>{orders.filter((order) => order.order_status === 'pending').length}</strong></article><article><small>Paid revenue</small><strong>{money(revenue, String(orders.find((order) => order.payment_status === 'paid')?.currency || ''))}</strong></article></div><section className="admin-panel"><h2>Recent orders</h2><AdminOrders orders={orders.slice(0, 10)} onStatus={updateOrder} /></section></>}{!loading && section === 'Products' && <section className="admin-panel"><div className="admin-panel-heading"><h2>Catalogue</h2><span>{products.length} products</span></div><form className="admin-product-form" onSubmit={saveProduct}><input placeholder="Name" value={draft.name} onChange={(event) => setDraft({ ...draft, name: event.target.value })} required /><input placeholder="Slug" value={draft.slug} onChange={(event) => setDraft({ ...draft, slug: event.target.value })} required /><input placeholder="SKU" value={draft.sku} onChange={(event) => setDraft({ ...draft, sku: event.target.value })} required /><input placeholder="Price" type="number" min="0" step="0.01" value={draft.price} onChange={(event) => setDraft({ ...draft, price: event.target.value })} required /><input placeholder="Currency (e.g. LKR)" value={draft.currency} onChange={(event) => setDraft({ ...draft, currency: event.target.value })} required /><input placeholder="Stock" type="number" min="0" value={draft.stock_quantity} onChange={(event) => setDraft({ ...draft, stock_quantity: event.target.value })} required /><input placeholder="Image URL (https://…)" value={draft.image} onChange={(event) => setDraft({ ...draft, image: event.target.value })} /><textarea placeholder="Description" value={draft.description} onChange={(event) => setDraft({ ...draft, description: event.target.value })} /><label><input type="checkbox" checked={draft.is_active} onChange={(event) => setDraft({ ...draft, is_active: event.target.checked })} /> Publish product</label><button className="admin-button" type="submit">{draft.id ? 'Save product' : 'Create product'}</button></form><AdminProducts products={products} onEdit={(product) => setDraft({ id: String(product.id), name: String(product.name || ''), slug: String(product.slug || ''), sku: String(product.sku || ''), price: String(product.price || ''), currency: String(product.currency || ''), stock_quantity: String(product.stock_quantity || ''), image: String(product.image || ''), description: String(product.description || ''), category_id: '', is_active: Boolean(product.is_active) })} /></section>}{!loading && section === 'Orders' && <section className="admin-panel"><h2>Orders</h2><AdminOrders orders={orders} onStatus={updateOrder} /> </section>}{error && <p className="admin-error">{error}</p>}</main></div>; }
function AdminProducts({ products, onEdit }: { products: Array<Record<string, unknown>>; onEdit: (product: Record<string, unknown>) => void }) { return products.length ? <div className="admin-table-wrap"><table className="admin-table"><thead><tr><th>Product</th><th>SKU</th><th>Price</th><th>Stock</th><th>Status</th><th /></tr></thead><tbody>{products.map((product) => <tr key={String(product.id)}><td>{String(product.name)}</td><td>{String(product.sku)}</td><td>{money(Number(product.price), String(product.currency || ''))}</td><td>{String(product.stock_quantity)}</td><td>{product.is_active ? 'Active' : 'Draft'}</td><td><button className="table-action" onClick={() => onEdit(product)}>Edit</button></td></tr>)}</tbody></table></div> : <p className="admin-empty">No products yet. Add the first verified product above.</p>; }
function AdminOrders({ orders, onStatus }: { orders: Array<Record<string, unknown>>; onStatus: (id: string, status: string) => void }) { return orders.length ? <div className="admin-table-wrap"><table className="admin-table"><thead><tr><th>Order</th><th>Customer</th><th>Amount</th><th>Payment</th><th>Order status</th></tr></thead><tbody>{orders.map((order) => <tr key={String(order.id)}><td>{String(order.order_number)}</td><td>{String(order.customer_name)}<small>{String(order.phone)}</small></td><td>{money(Number(order.grand_total), String(order.currency || ''))}</td><td>{String(order.payment_method)} · {String(order.payment_status)}</td><td><select value={String(order.order_status)} onChange={(event) => onStatus(String(order.id), event.target.value)}><option value="pending">Pending</option><option value="confirmed">Confirmed</option><option value="processing">Processing</option><option value="shipped">Shipped</option><option value="delivered">Delivered</option><option value="cancelled">Cancelled</option></select></td></tr>)}</tbody></table></div> : <p className="admin-empty">No orders yet.</p>; }

function App() { const route = window.location.pathname; if (route.startsWith('/admin')) return <AdminApp route={route} />; const catalog = useCatalog(); const [path, setPath] = useState(window.location.pathname + window.location.search); const [cart, setCart] = useState<CartLine[]>(readCart); const [searchOpen, setSearchOpen] = useState(false); useEffect(() => { const listener = () => setPath(window.location.pathname + window.location.search); window.addEventListener('popstate', listener); return () => window.removeEventListener('popstate', listener); }, []); useEffect(() => { localStorage.setItem('antz-soft-haven-cart', JSON.stringify(cart)); }, [cart]); useEffect(() => { const base = import.meta.env.VITE_SITE_URL || window.location.origin; const canonical = document.querySelector('link[rel="canonical"]') as HTMLLinkElement | null; if (canonical) canonical.href = `${base}${window.location.pathname}`; const slug = path.split('/').filter(Boolean).pop(); document.title = path === '/' ? 'ANTZ SoftHaven | Premium Plush Toys' : `${slug ? slug.replace(/-/g, ' ') : 'ANTZ SoftHaven'} | ANTZ SoftHaven`; }, [path]); const add = (productId: string) => setCart((current) => { const existing = current.find((line) => line.productId === productId); return existing ? current.map((line) => line.productId === productId ? { ...line, quantity: line.quantity + 1 } : line) : [...current, { productId, quantity: 1 }]; }); const content = catalog.loading ? <StoreState message="Loading the live catalogue…" /> : path === '/' ? <Home products={catalog.products} categories={catalog.categories} onAdd={add} settings={catalog.settings} configured={!catalog.error} /> : path === '/shop' || path.startsWith('/shop?') ? <Shop products={catalog.products} categories={catalog.categories} onAdd={add} /> : path === '/collections' ? <Collections categories={catalog.categories} products={catalog.products} onAdd={add} /> : path.startsWith('/product/') ? <ProductPage product={catalog.products.find((item) => item.slug === path.split('/')[2])} onAdd={add} /> : path === '/cart' ? <CartPage cart={cart} products={catalog.products} setCart={setCart} settings={catalog.settings} /> : path === '/checkout' ? <Checkout cart={cart} products={catalog.products} shipping={catalog.shipping} payments={catalog.payments} settings={catalog.settings} onSuccess={(receipt) => { sessionStorage.setItem('antz-soft-haven-order', JSON.stringify(receipt)); setCart([]); navigate('/order-confirmed'); }} /> : path === '/order-confirmed' ? <OrderConfirmation settings={catalog.settings} payments={catalog.payments} /> : path === '/contact' ? <Contact settings={catalog.settings} /> : path === '/about' ? <About /> : policyTitles[path] ? <Legal path={path} settings={catalog.settings} /> : path === '/faq' ? <Faq /> : <NotFound />; return <Layout settings={catalog.settings} cartCount={cart.reduce((sum, line) => sum + line.quantity, 0)} onSearch={() => setSearchOpen(true)}>{content}{searchOpen && <SearchModal onClose={() => setSearchOpen(false)} />}</Layout>; }
function SearchModal({ onClose }: { onClose: () => void }) { const [value, setValue] = useState(''); return <div className="search-modal" role="dialog" aria-modal="true" aria-label="Search SoftHaven" onClick={onClose}><div onClick={(event) => event.stopPropagation()}><button aria-label="Close search" onClick={onClose}><Icon name="close" /></button><span className="eyebrow">Search SoftHaven</span><form onSubmit={(event) => { event.preventDefault(); onClose(); navigate(`/shop?q=${encodeURIComponent(value.trim())}`); }}><input autoFocus placeholder="Search products or collections" value={value} onChange={(event) => setValue(event.target.value)} /><Button type="submit">Search</Button></form></div></div>; }

createRoot(document.getElementById('root')!).render(<App />);
